game=None
map_data=None
class Maps():
	def set_main_game(game_):
		global game
		game=game_
	def set_map_data():
		global map_data
		map_data=game.map_data

def convert_tiled(map_,width,height):
	m=[]
	for i in range(1,height+1):
		m.append(map_[slice(width*(i-1),width*(i))])

	return m
def convert_obj(data):
	list_=[(tile["gid"],(round(tile["x"]),round(tile["y"]) )) for tile in data]		
	return list_
